<div class="headline"><div><h1>Participantes</h1><p class="subtitle">Administra la información de los deportistas.</p></div><a class="btn" href="<?= h(url('participante_form')) ?>">+ Nuevo participante</a></div>
            <section class="panel"><form class="search" method="get"><input type="hidden" name="page" value="participantes"><input type="search" name="q" placeholder="Buscar por nombre o correo" value="<?= h($q) ?>"><button class="btn btn-light">Buscar</button></form></section>
